from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  // quality is a soft-delete marker set by Node-RED (ok|empty) and by
  // mark-weight.sh after the fact. Nothing is dropped from the database; the
  // charts simply show the readings currently believed good.
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  |> keep(columns: ["_time", "_value", "plant_id"])

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  // quality is a soft-delete marker set by Node-RED (ok|empty) and by
  // mark-weight.sh after the fact. Nothing is dropped from the database; the
  // charts simply show the readings currently believed good.
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  // Carry the weight and the timestamp as plain numbers, then take ONE difference
  // over both: the weight change and the time gap come out on the same row by
  // construction. Using elapsed() + difference() instead drops two rows rather than
  // one, so the first interval of every series vanished silently.
  |> map(fn: (r) => ({ r with w: r._value, t: float(v: int(v: r._time)) }))
  |> difference(columns: ["w", "t"], nonNegative: false)
  |> map(fn: (r) => ({ r with hours: r.t / 3600000000000.0 }))
  // A rate only means something across a GAP. Two readings from the same session —
  // a repeat, or the pre/post pair around watering — are minutes apart, and
  // dividing by that produces nonsense (one such pair works out at -10512 g/day).
  // This also guarantees the divisor is never zero.
  |> filter(fn: (r) => r.hours >= 1.0)
  // An interval containing a watering is not a use interval. The pot GAINED, so
  // the formula reports it as hugely negative "use" — and the shorter the gap,
  // the louder: cactus-19's first two readings, 4.2 h apart around an evening
  // watering, came out at -249 g/day.
  //
  // A longer minimum gap does NOT fix this, which the data says plainly. Measured
  // over 60 days, extremes appear in every interval band including >=20 h
  // (-119 g/day there), while splitting on "did it gain more than 10 g" separates
  // cleanly: 33 watered intervals span -249..-5 and every one is negative, and
  // dropping them pulls the remaining 339 from a -249 floor up to -42.
  //
  // 10 g is the same watering threshold the session-detection panels use.
  |> filter(fn: (r) => r.w <= 10.0)
  // Sign flipped so positive = the plant drank it.
  |> map(fn: (r) => ({ r with _value: -r.w / r.hours * 24.0 }))
  |> keep(columns: ["_time", "_value", "plant_id"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  |> map(fn: (r) => ({ r with w: r._value, t: float(v: int(v: r._time)) }))
  |> difference(columns: ["w", "t"], nonNegative: false)
  |> map(fn: (r) => ({ r with hours: r.t / 3600000000000.0, _value: r.w }))
  // ESTIMATED: no pre-water weighing that session, so the pair spans a gap and the
  // figure is water added MINUS whatever the plant used in between. Worse, across a
  // gap the two populations overlap — the largest drift seen is +13.0 g and the
  // smallest real watering caught this way is +20.2 g, barely 7 g apart. 15 g is
  // therefore a judgement call, not a clean separation; treat these bars as a hint
  // and fix the protocol instead (always weigh before watering).
  |> filter(fn: (r) => r.hours >= 1.0 and r._value > 15.0)
  |> keep(columns: ["_time", "_value", "plant_id"])
  |> yield(name: "estimated")

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

// 10 g 是全域的澆水判定門檻，與面板 2 的速率過濾、面板 11 的場次偵測同一個值。
JUMP = 10.0

src = (start) => from(bucket: "sensors")
  |> range(start: start)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g"
       and r.quality == "ok" and r.plant_id != "unknown")
  |> keep(columns: ["_time", "_value", "plant_id"])

// ---- 只看還在養的盆 ----
// 一顆 NFC tag 同時只會貼在一個盆上,所以「這顆 uid 最近一次讀值屬於哪個
// plant_id」就是它現在的主人。換盆時 tag 移交給後繼者(cactus-03 -> 03b),
// 舊 id 從此不再是任何 uid 的主人 —— 那就是「退役」的可觀測定義。
//
// 這個系統沒有退役旗標,而陳舊天數在這裡行不通:被換掉的盆最後一筆讀值就在
// 換盆前不久,和一個單純幾天沒澆的盆分不開。uid 的歸屬則是當下事實。
// 2026-08-31 實測:判出 26 株,正好等於 tag-map 的 26 筆綁定。
live = from(bucket: "sensors")
  |> range(start: -90d)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "uid"
       and r.plant_id != "unknown")
  |> group(columns: ["_value"])          // 依 uid 分組
  |> last()                              // 每顆 uid 最近的一筆
  |> group()
  |> findColumn(fn: (key) => true, column: "plant_id")

// 錨點是「這一株自己上次被澆水」，不是「上一個全體澆水場次」。
// 舊版用後者，於是沒被澆到的那幾株，sat 取到的是它們自己偏乾的近期讀值,
// sat 幾乎等於 now、耗竭算出 0% —— 最需要水的反而顯示成不用澆。
// 2026-08-22 實測：cactus-08/12/13-2 當天沒澆，舊版全報 0%，實際是 40-52%。
anchor = src(start: -90d)
  |> group(columns: ["plant_id"]) |> sort(columns: ["_time"])
  |> difference(columns: ["_value"], nonNegative: false)
  |> filter(fn: (r) => r._value > JUMP)
  |> group(columns: ["plant_id"]) |> last(column: "_value")
  |> map(fn: (r) => ({ plant_id: r.plant_id, anchor: r._time }))
  |> group()

// 飽和重量 = 自己那次澆水之後的最大值
satW = join(tables: {s: src(start: -90d) |> group(), a: anchor}, on: ["plant_id"])
  |> filter(fn: (r) => r._time >= r.anchor)
  |> group(columns: ["plant_id"]) |> max(column: "_value")
  |> map(fn: (r) => ({ plant_id: r.plant_id, k: "sat", v: r._value }))
  |> group()

nowW = src(start: -90d) |> group(columns: ["plant_id"]) |> last()
  |> map(fn: (r) => ({ plant_id: r.plant_id, k: "now", v: r._value }))

// 距離自己上次澆水幾天 —— 每株各自計算
ageW = anchor
  |> map(fn: (r) => ({ plant_id: r.plant_id, k: "days",
       v: float(v: int(v: now()) - int(v: r.anchor)) / 86400000000000.0 }))

// ---- 分母：已完結澆水循環中，實測到的最大一次回落幅度 ----
// 舊版用「sat − 60 天 p10」。那個 p10 取到的是上秤初期、盆子已乾很久的狀態，
// 現在的澆水習慣從不回到那裡 —— 分母裡有一大塊是週級尺度上既不會被用掉、
// 也不會被一次澆水補回來的深層核心水。大盆因此分母約 2 倍過大：
// 實測循環幅度 ÷ 舊分母，>1300 g 的盆是 0.38–0.63，<500 g 的盆是 0.71–1.30。
// 於是 80% 這個門檻等於是被小盆校準出來的，大盆永遠不會亮。
//
// 每筆標上它屬於第幾個澆水循環。difference 只覆寫 _value，先 duplicate 出 wt
// 就能同時保有原重量與差分。group 之後補一次 sort：Flux 不保證 group 維持列序，
// 而 last() 依賴它。
cyc = src(start: -60d)
  |> group(columns: ["plant_id"]) |> sort(columns: ["_time"])
  |> duplicate(column: "_value", as: "wt")
  |> difference(columns: ["_value"], nonNegative: false, keepFirst: true)
  |> map(fn: (r) => ({ r with isw: if exists r._value and r._value > JUMP then 1 else 0 }))
  |> cumulativeSum(columns: ["isw"])
  |> group(columns: ["plant_id", "isw"]) |> sort(columns: ["_time"])

hi = cyc |> max(column: "wt")
  |> map(fn: (r) => ({ plant_id: r.plant_id, c: r.isw, k: "hi", v: r.wt })) |> group()
lo = cyc |> last(column: "wt")
  |> map(fn: (r) => ({ plant_id: r.plant_id, c: r.isw, k: "lo", v: r.wt })) |> group()
cmax = cyc |> last(column: "wt") |> group(columns: ["plant_id"]) |> max(column: "isw")
  |> map(fn: (r) => ({ plant_id: r.plant_id, cmax: r.isw })) |> group()

drops = union(tables: [hi, lo]) |> group()
  |> pivot(rowKey: ["plant_id", "c"], columnKey: ["k"], valueColumn: "v")
  |> map(fn: (r) => ({ plant_id: r.plant_id, c: r.c, drop: r.hi - r.lo }))

// c > 0     ：c = 0 是「窗口左緣 → 第一次澆水」的左截斷殘段，起點不是澆水，
//             不算完結循環。實測 6/23 盆的殘段 >= 10 g（cactus-12 是 37 g）。
// c < cmax  ：排除進行中的那一輪。
// drop>=JUMP：排除順手補水造成的零幅度循環。
spanCyc = join(tables: {d: drops, m: cmax}, on: ["plant_id"])
  |> filter(fn: (r) => r.c > 0 and r.c < r.cmax and r.drop >= JUMP)
  |> group(columns: ["plant_id"]) |> max(column: "drop")
  |> map(fn: (r) => ({ plant_id: r.plant_id, k: "cycsp", v: r.drop }))
  |> group()

// 尚無完結循環的新盆暫用舊的 p10 定義，basis 欄會標示出來。
// spanCyc 全空時 pivot 不會產生 cycsp 欄，exists 在該情況下回傳 false
// 並落到這條退路（實測確認，不需要哨兵列）。
p10W = src(start: -60d) |> group(columns: ["plant_id"])
  |> quantile(q: 0.1, method: "exact_mean")
  |> map(fn: (r) => ({ plant_id: r.plant_id, k: "p10", v: r._value }))

union(tables: [nowW, satW, p10W, ageW, spanCyc]) |> group()
  |> pivot(rowKey: ["plant_id"], columnKey: ["k"], valueColumn: "v")
  |> map(fn: (r) => ({ r with
       span: if exists r.cycsp then r.cycsp else r.sat - r.p10,
       basis: if exists r.cycsp then "循環" else "暫用 p10" }))
  |> filter(fn: (r) => r.span > 5.0)
  |> map(fn: (r) => ({
       plant_id: r.plant_id,
       now_g: r.now, sat_g: r.sat, trig_g: r.sat - r.span, span_g: r.span,
       basis: r.basis,
       depl_pct: (r.sat - r.now) / r.span * 100.0,
       days: r.days }))
  |> map(fn: (r) => ({ r with
       habit: if r.depl_pct >= 100.0 then "● 該澆水" else "○",
       obs80: if r.depl_pct >= 80.0 then "● 該澆水" else "○" }))
  |> filter(fn: (r) => contains(value: r.plant_id, set: live))
  |> sort(columns: ["depl_pct"], desc: true)
  |> keep(columns: ["plant_id","now_g","sat_g","trig_g","span_g","basis",
                    "depl_pct","habit","obs80","days"])

import "date"
import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "light" and r._field == "on" and r._value == 0.0)
  |> map(fn: (r) => ({ r with _value: float(v: date.hour(t: r._time)) + float(v: date.minute(t: r._time)) / 60.0 }))
  // Keep only plausible lamp-off times. `light/state` is RETAINED, so every
  // Telegraf reconnect replays it and lands a phantom OFF at the restart time —
  // one such artifact sits at 22:44 on 2026-07-30. The real switch-off is always
  // in the evening window, so anything outside it is not a lamp event.
  |> filter(fn: (r) => r._value >= 17.0 and r._value <= 21.5)
  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "lamp off (hour of day)")

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

base = from(bucket: "sensors") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)

// One representative field per measurement — counting every field would mix
// value types in one group, which aggregateWindow rejects.
union(tables: [
  base |> filter(fn: (r) => r._measurement == "air" and r._field == "lux"),
  base |> filter(fn: (r) => r._measurement == "spectrum" and r._field == "f555"),
  base |> filter(fn: (r) => r._measurement == "weather" and r._field == "temperature_2m"),
  base |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g"),
  // The alert-delivery scrape. If this row goes flat, we have stopped being able to
  // tell whether warnings reach anyone — the same blindness as 2026-08-08, one
  // level up. It is absent until Grafana's first notification attempt after a
  // restart, so a gap right after a restart is expected, not a fault.
  base |> filter(fn: (r) => r._measurement == "grafana_alerting_notifications_total" and r._field == "counter"),
])
  |> group(columns: ["_measurement"])
  |> aggregateWindow(every: 1d, fn: count, createEmpty: true)
  |> keep(columns: ["_time", "_value", "_measurement"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "ppfd_cal" and r.device == "livingroom")
  // window_mode has to survive the pivot, so it belongs in the rowKey. Without it
  // the two windows collapse into one line that steps between two different
  // optical conditions — which reads exactly like sensor drift, the false signal
  // this dashboard already produced once.
  // Drop untagged series BEFORE the pivot, not after: pivot requires every rowKey
  // column to exist in every input table, so a single pre-tag point makes the
  // whole query fail with "specified row key column does not exist". Two such
  // points exist, from 2026-08-16/17, and they cannot be attributed to a mode.
  |> filter(fn: (r) => exists r.window_mode)
  |> pivot(rowKey: ["_time", "window_mode"], columnKey: ["_field"], valueColumn: "_value")
  // Only days the fit actually passed. A valid=0 day has no meaningful cal_ols —
  // plotting it would put a number on the chart that the run itself rejected.
  // Why a day is missing is the neighbouring table's job, not this one's.
  |> filter(fn: (r) => r.valid == 1.0 and exists r.cal_ols)
  |> map(fn: (r) => ({_time: r._time, window_mode: r.window_mode, _value: r.cal_ols}))
  // One series per mode: separate lines, each labelled, never one mixed line.
  |> group(columns: ["window_mode"])
  |> keep(columns: ["_time", "_value", "window_mode"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "ppfd_cal" and r.device == "livingroom")
  // Drop untagged series BEFORE the pivot, not after: pivot requires every rowKey
  // column to exist in every input table, so a single pre-tag point makes the
  // whole query fail with "specified row key column does not exist". Two such
  // points exist, from 2026-08-16/17, and they cannot be attributed to a mode.
  |> filter(fn: (r) => exists r.window_mode)
  |> pivot(rowKey: ["_time", "window_mode"], columnKey: ["_field"], valueColumn: "_value")
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> keep(columns: ["_time", "window_mode", "valid", "skipped", "lamp_off_ok",
       "n_kept", "lux_lo", "lux_hi", "cal_ols", "r2", "drift_pct"])
